var now = new Date();
var pad = function(n) { return String(n).padStart(2, '0'); };
var datePart = [now.getFullYear(), pad(now.getMonth() + 1), pad(now.getDate())].join('');
var timePart = [pad(now.getHours()), pad(now.getMinutes()), pad(now.getSeconds())].join('');
var batchId = datePart + '-' + timePart;

return [{
  json: {
    batchId: batchId,
    runStartedAt: now.toISOString()
  }
}];

var token = $node['Config'].json.APIFY_API_TOKEN;
var keyword = $json.keyword;
var hashtag = keyword.replace(/\s+/g, '').toLowerCase();

try {
  var response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.apify.com/v2/acts/apify~instagram-scraper/runs?token=' + token,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      directUrls: ['https://www.instagram.com/explore/tags/' + hashtag + '/'],
      resultsType: 'posts',
      resultsLimit: 300,
      addParentData: false
    })
  });
  return [{ json: { data: response.data || response, keyword: keyword, platform: $json.platform, error: false } }];
} catch (e) {
  return [{ json: { data: null, keyword: keyword, platform: $json.platform, error: true, errorMessage: e.message } }];
}

if ($json.error === true) {
  return [{ json: { usernames: [], directUrls: [], usernameCount: 0, keyword: $json.keyword, platform: $json.platform, skipped: true } }];
}

var rawInput = $input.all();
var usernames = [];
var seen = {};

var allPosts = [];
for (var i = 0; i < rawInput.length; i++) {
  var data = rawInput[i].json;
  if (Array.isArray(data)) {
    for (var k = 0; k < data.length; k++) { allPosts.push(data[k]); }
  } else if (data) {
    allPosts.push(data);
  }
}

for (var j = 0; j < allPosts.length; j++) {
  var post = allPosts[j];
  var username = (post.ownerUsername || post.username || '').toLowerCase().trim();
  if (username && !seen[username]) {
    seen[username] = true;
    usernames.push(username);
  }
}

var directUrls = [];
for (var k = 0; k < usernames.length; k++) {
  directUrls.push('https://www.instagram.com/' + usernames[k] + '/');
}

var keyword = $node['Loop Over Keywords'].json.keyword || 'unknown';
var platform = $node['Set Platform'].json.platform || 'instagram';

return [{
  json: {
    usernames: usernames,
    directUrls: directUrls,
    usernameCount: usernames.length,
    keyword: keyword,
    platform: platform
  }
}];

var usernames = $json.usernames || [];

if (usernames.length === 0) {
  return [{
    json: {
      skipped: true,
      reason: 'No usernames extracted from search results',
      keyword: $json.keyword,
      platform: $json.platform
    }
  }];
}

if (usernames.length > 40) { usernames = usernames.slice(0, 40); }

var directUrls = [];
for (var i = 0; i < usernames.length; i++) {
  directUrls.push('https://www.instagram.com/' + usernames[i] + '/');
}

return [{
  json: {
    requestBody: JSON.stringify({
      usernames: usernames,
      resultsLimit: 500
    }),
    keyword: $json.keyword,
    platform: $json.platform,
    usernameCount: usernames.length,
    directUrls: directUrls,
    skipped: false
  }
}];

var results = $input.all().map(function(item) { return item.json; });
var validResults = results.filter(function(r) { return !r.error && !r.errorDescription; });

if (validResults.length === 0) {
  return [{ json: { hasResults: false, resultCount: 0, errorMessage: (results[0] && results[0].errorDescription) ? results[0].errorDescription : 'No results returned' } }];
}

var output = [];
for (var i = 0; i < validResults.length; i++) {
  output.push({ json: Object.assign({}, validResults[i], { hasResults: true }) });
}
return output;

var platform = 'instagram';
try { platform = $node['Set Platform'].json.platform || 'instagram'; } catch(e) {}

var MIN_FOLLOWERS = 200;
var MAX_FOLLOWERS = 500000;
var MAX_DAYS_SINCE_POST = 90;

var PT_BIO_KEYWORDS = [
  'personal trainer', 'personal training', 'fitness trainer', 'strength coach',
  'fitness coach', 'certified trainer', 'accredited', 'cert iv', 'certificate iv',
  'physique coach', 'body transformation', 'weight loss coach', 'online coach',
  'gym coach', 'pt |', '| pt', 'pt/', '/pt', 'exercise scientist', 'exercise physiologist'
];

function daysAgo(dateStr) {
  if (!dateStr) return 0;
  var date = new Date(dateStr);
  if (isNaN(date.getTime())) return 0;
  var diffMs = Date.now() - date.getTime();
  return Math.floor(diffMs / (1000 * 60 * 60 * 24));
}

function getBioScore(bio) {
  if (!bio) return 0;
  var lower = bio.toLowerCase();
  for (var k = 0; k < PT_BIO_KEYWORDS.length; k++) {
    if (lower.indexOf(PT_BIO_KEYWORDS[k]) !== -1) return 1;
  }
  return 0;
}

var rawProfiles = $input.all().map(function(item) { return item.json; });
var seen = {};
var passed = [];

for (var i = 0; i < rawProfiles.length; i++) {
  var raw = rawProfiles[i];

  var username = (raw.username || raw.handle || raw.userName || '').toLowerCase().trim();
  if (!username || seen[username]) continue;
  seen[username] = true;

  var followerCount = parseInt(raw.followersCount || raw.followers || raw.follower_count || raw.edge_followed_by_count || 0, 10);
  var lastPostDate = raw.latestPostDate || raw.recentPostTimestamp || raw.last_post_date || raw.latestMediaDate || '';

  if (followerCount > 0 && followerCount < MIN_FOLLOWERS) continue;
  if (followerCount > MAX_FOLLOWERS) continue;
  if (lastPostDate && daysAgo(lastPostDate) > MAX_DAYS_SINCE_POST) continue;

  var bio = raw.biography || raw.bio || raw.description || raw.aboutText || '';
  var bioQualified = getBioScore(bio) === 1;
  var followingCount = parseInt(raw.followingCount || raw.following || raw.follows || 0, 10);
  var postsCount = parseInt(raw.postsCount || raw.posts_count || raw.mediaCount || raw.edge_owner_to_timeline_media_count || 0, 10);
  var displayName = raw.fullName || raw.name || raw.display_name || raw.full_name || '';
  var profileUrl = raw.profileUrl || raw.url || raw.profile_url || '';
  if (!profileUrl && username) {
    profileUrl = 'https://www.instagram.com/' + username + '/';
  }
  var isBusinessAccount = raw.isBusinessAccount || raw.businessAccount || raw.is_business_account || false;
  var isVerified = raw.verified || raw.isVerified || raw.is_verified || false;
  var externalUrl = raw.externalUrl || raw.external_url || raw.website || '';
  var locationRaw = raw.locationCity || raw.locationName || raw.location || raw.city || '';
  var email = raw.businessEmail || raw.publicEmail || raw.email || '';
  var phone = raw.businessPhone || raw.contactPhoneNumber || raw.phone || '';
  var category = raw.businessCategory || raw.categoryName || raw.category || '';

  passed.push({
    json: {
      platform: platform,
      username: username,
      displayName: displayName,
      bio: bio,
      followerCount: followerCount,
      followingCount: followingCount,
      postsCount: postsCount,
      profileUrl: profileUrl,
      profilePicUrl: raw.profilePicUrl || raw.profile_pic_url || '',
      lastPostDate: lastPostDate,
      isBusinessAccount: isBusinessAccount,
      isVerified: isVerified,
      externalUrl: externalUrl,
      locationRaw: locationRaw,
      email: email,
      phone: phone,
      category: category,
      tags: bioQualified ? ['phase-1-import', 'bio-qualified'] : ['phase-1-import', 'bio-unverified'],
      keywordType: 'primary',
      bioQualified: bioQualified
    }
  });
}

return passed.length > 0 ? passed : [{ json: { skipped: true, reason: 'No profiles passed filter' } }];

// FIX: Use modern n8n API to load sheet rows, with fallback to old API
var sheetData = [];
try {
  var sheetItems = $('Load Sheet Data').all();
  for (var s = 0; s < sheetItems.length; s++) {
    sheetData.push(sheetItems[s].json);
  }
} catch(e1) {
  try {
    var fallbackItems = $items('Load Sheet Data');
    for (var f = 0; f < fallbackItems.length; f++) {
      sheetData.push(fallbackItems[f].json);
    }
  } catch(e2) {
    sheetData = [];
  }
}

// Per-run dedup tracker using static data - resets when batch ID changes
var staticData = $getWorkflowStaticData('node');
var currentBatchId = '';
try { currentBatchId = $node['Generate Batch ID'].json.batchId || ''; } catch(e) {}
if (staticData.batchId !== currentBatchId) {
  staticData.batchId = currentBatchId;
  staticData.processedUsernames = {};
}

// Build lookup of all usernames already in the sheet
var existingUsernames = {};
for (var i = 0; i < sheetData.length; i++) {
  var row = sheetData[i];
  var uname = (row.username || row.Username || '').toLowerCase().trim();
  if (uname) existingUsernames[uname] = true;
}

// Also include usernames already processed in this run (cross-keyword dedup)
var processedKeys = Object.keys(staticData.processedUsernames || {});
for (var p = 0; p < processedKeys.length; p++) {
  existingUsernames[processedKeys[p]] = true;
}

var incoming = $input.all().map(function(item) { return item.json; });
var newProfiles = [];

for (var j = 0; j < incoming.length; j++) {
  var profile = incoming[j];
  if (profile.skipped) continue;
  var username = (profile.username || '').toLowerCase().trim();
  if (username && existingUsernames[username]) continue;
  if (username) {
    staticData.processedUsernames[username] = true;
    existingUsernames[username] = true;
  }
  newProfiles.push({ json: profile });
}

if (newProfiles.length === 0) return [];
return newProfiles;

// FIX: Search GHL by website field containing IG username - reliable dedup
var config = $node['Config'].json;
var profile = $input.first().json;
var username = (profile.username || '').toLowerCase().trim();
var searchValue = 'instagram.com/' + username;

var total = 0;
try {
  var res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://services.leadconnectorhq.com/contacts/search',
    headers: {
      'Authorization': 'Bearer ' + config.GHL_API_TOKEN,
      'Content-Type': 'application/json',
      'Version': '2021-07-28'
    },
    body: JSON.stringify({
      locationId: config.GHL_LOCATION_ID,
      filters: [{ field: 'website', operator: 'contains', value: searchValue }],
      pageLimit: 5
    })
  });
  total = (res.contacts || []).length;
} catch(e) {
  total = 0;
}

return [{ json: { total: total } }];

var profile = $node['Loop Over Filtered Profiles'].json;
var batchId = '';
try { batchId = $node['Generate Batch ID'].json.batchId; } catch(e) {}
var scrapeDate = new Date().toISOString().split('T')[0];

var tags = [
  'source:apify',
  'new-lead',
  'phase-1-import',
  'platform:' + (profile.platform || 'instagram'),
  'batch:' + scrapeDate
];

if (profile.tags && Array.isArray(profile.tags)) {
  for (var t = 0; t < profile.tags.length; t++) {
    tags.push(profile.tags[t]);
  }
}

if (profile.isBusinessAccount) tags.push('business-account');
if (profile.isVerified) tags.push('verified');

var displayName = profile.displayName || profile.username || '';
var firstName = 'Unknown';
var lastName = '';

if (displayName && displayName.trim() !== '') {
  var parts = displayName.trim().split(/\s+/);
  firstName = parts[0] || 'Unknown';
  lastName = parts.slice(1).join(' ') || '';
}

var website = profile.profileUrl || '';
if (!website && profile.username) {
  website = 'https://www.instagram.com/' + profile.username + '/';
}

var noteLines = [];
noteLines.push('=== Phase 1 Discovery Scrape ===');
noteLines.push('Scraped: ' + scrapeDate);
noteLines.push('Platform: ' + (profile.platform || 'instagram'));
noteLines.push('Username: @' + (profile.username || 'unknown'));
noteLines.push('Batch: ' + batchId);
noteLines.push('');
noteLines.push('=== Profile Info ===');
noteLines.push('Bio: ' + (profile.bio || 'N/A'));
noteLines.push('Followers: ' + (profile.followerCount || 0));
noteLines.push('Following: ' + (profile.followingCount || 0));
noteLines.push('Posts: ' + (profile.postsCount || 0));
noteLines.push('Last Post: ' + (profile.lastPostDate || 'unknown'));
noteLines.push('Location: ' + (profile.locationRaw || 'unknown'));
noteLines.push('Business Account: ' + (profile.isBusinessAccount ? 'Yes' : 'No'));
noteLines.push('Verified: ' + (profile.isVerified ? 'Yes' : 'No'));
noteLines.push('Category: ' + (profile.category || 'N/A'));
noteLines.push('');
if (profile.externalUrl) noteLines.push('External URL: ' + profile.externalUrl);
if (profile.email) noteLines.push('Business Email: ' + profile.email);
if (profile.phone) noteLines.push('Business Phone: ' + profile.phone);

return [{ json: {
  firstName: firstName,
  lastName: lastName,
  locationId: $node['Config'].json.GHL_LOCATION_ID,
  website: website,
  tags: tags,
  source: 'apify-scrape',
  email: profile.email || '',
  phone: profile.phone || '',
  bio: profile.bio || '',
  followerCount: profile.followerCount || 0,
  postsCount: profile.postsCount || 0,
  lastPostDate: profile.lastPostDate || '',
  category: profile.category || '',
  internalNote: noteLines.join('\n')
} }];

var contactId = '';
if ($json.contact && $json.contact.id) {
  contactId = $json.contact.id;
} else if ($json.id) {
  contactId = $json.id;
} else if ($json.contactId) {
  contactId = $json.contactId;
}

if (!contactId) {
  return [{ json: { error: 'No contact ID for note', skipped: true } }];
}

var noteBody = $node['Transform For GHL'].json.internalNote || 'Phase 1 import - no details captured';
var config = $node['Config'].json;

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://services.leadconnectorhq.com/contacts/' + contactId + '/notes',
    headers: {
      'Authorization': 'Bearer ' + config.GHL_API_TOKEN,
      'Content-Type': 'application/json',
      'Version': '2021-07-28'
    },
    body: JSON.stringify({ body: noteBody })
  });
  return [{ json: { contactId: contactId, noteAdded: true } }];
} catch (e) {
  return [{ json: { contactId: contactId, noteAdded: false, error: e.message } }];
}

var config = $node['Config'].json;
var contactId = $json.contact && $json.contact.id ? $json.contact.id : ($json.id || $json.contactId || '');

if (!contactId) {
  return [{ json: Object.assign({}, $json, { opportunityError: 'No contact ID', opportunityId: null }) }];
}

try {
  var firstName = '';
  var lastName = '';
  try { firstName = $('Transform For GHL').first().json.firstName || 'Lead'; } catch(e) {}
  try { lastName = $('Transform For GHL').first().json.lastName || ''; } catch(e) {}

  var opportunity = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://services.leadconnectorhq.com/opportunities/',
    headers: {
      'Authorization': 'Bearer ' + config.GHL_API_TOKEN,
      'Content-Type': 'application/json',
      'Version': '2021-07-28'
    },
    body: JSON.stringify({
      pipelineId: config.GHL_PIPELINE_ID,
      locationId: config.GHL_LOCATION_ID,
      pipelineStageId: config.GHL_STAGE_IDENTIFIED_ID,
      contactId: contactId,
      name: firstName + ' ' + lastName + ' - Discovery',
      status: 'open'
    })
  });
  var oppId = (opportunity.opportunity && opportunity.opportunity.id) ? opportunity.opportunity.id : (opportunity.id || null);
  return [{ json: Object.assign({}, $json, { opportunityId: oppId }) }];
} catch (e) {
  return [{ json: Object.assign({}, $json, { opportunityError: e.message, opportunityId: null }) }];
}

var now = new Date().toISOString();
var keyword = '';
var platform = '';
var batchId = '';
try { keyword = $node['Loop Over Keywords'].json.keyword || 'unknown'; } catch(e) {}
try { platform = $node['Set Platform'].json.platform || 'unknown'; } catch(e) {}
try { batchId = $node['Generate Batch ID'].json.batchId || 'unknown'; } catch(e) {}

return [{
  json: {
    timestamp: now,
    severity: 'medium',
    errorType: 'APIFY_ZERO_RESULTS',
    phase: 'Phase 1 - Discovery',
    keyword: keyword,
    platform: platform,
    batchId: batchId,
    message: ($input.first().json.errorMessage || 'No results returned from scraper'),
    summary: 'Apify returned 0 valid results for keyword "' + keyword + '" on ' + platform + '. Skipping to next keyword.'
  }
}];

var errorContext = $input.first().json;
var now = new Date().toISOString();

var ERROR_TYPES = {
  APIFY_ACTOR_FAILED:  { severity: 'high',   retry: true  },
  APIFY_ZERO_RESULTS:  { severity: 'medium', retry: false },
  GHL_API_RATE_LIMIT:  { severity: 'medium', retry: true  },
  GHL_API_FAILURE:     { severity: 'high',   retry: true  },
  GHL_IMPORT_FAILED:   { severity: 'medium', retry: true  },
  FILTER_SCRIPT_ERROR: { severity: 'high',   retry: false },
  UNKNOWN:             { severity: 'medium', retry: false }
};

var errorType = errorContext.errorType || 'UNKNOWN';
var errorMeta = ERROR_TYPES[errorType] || ERROR_TYPES.UNKNOWN;

return [{ json: {
  timestamp: now,
  severity: errorMeta.severity,
  errorType: errorType,
  shouldRetry: errorMeta.retry,
  phase: 'Phase 1 - Discovery',
  context: {
    platform: errorContext.platform || 'unknown',
    keyword: errorContext.keyword || 'unknown',
    batchId: errorContext.batchId || 'unknown',
    message: errorContext.message || 'No message provided'
  },
  summary: errorContext.summary || 'Unknown error in Phase 1 Discovery pipeline'
} }];

