// FIX: Use modern API with try-catch fallback for reliable count reporting
var imported = 0;
var skipped = 0;
var batchId = '';

try { batchId = $node['Generate Batch ID'].json.batchId; } catch(e) {}

try { imported = $('Log Import Success').all().length; } catch(e) {
  try { imported = $items('Log Import Success').length; } catch(e2) { imported = 0; }
}

try { skipped = $('Log Dedup Skip').all().length; } catch(e) {
  try { skipped = $items('Log Dedup Skip').length; } catch(e2) { skipped = 0; }
}

return [{
  json: {
    batchId: batchId,
    runCompletedAt: new Date().toISOString(),
    contacts_imported: imported,
    contacts_skipped_dedup: skipped,
    total_processed: imported + skipped
  }
}];

parameters.text:
=*Phase 1 Discovery Run Complete*

*Batch:* {{$json.batchId}}
*Completed:* {{$json.runCompletedAt}}

*Contacts imported:* {{$json.contacts_imported}}
*Contacts skipped (dedup):* {{$json.contacts_skipped_dedup}}
*Total processed:* {{$json.total_processed}}
*Apify Cost:* ${{$json.costUsd}} ({{$json.totalRuns}} actor runs)

parameters.jsCode:
var config = $('Config').first().json;
var apifyToken = config.APIFY_API_TOKEN || '';
var summary = $input.first().json;
var today = new Date().toISOString().split('T')[0];

var ACTOR_IDS = [
  'apify~instagram-scraper',
  'apify~instagram-profile-scraper'
];

var twoHoursAgo = new Date(Date.now() - 2 * 60 * 60 * 1000).toISOString();
var totalCostUsd = 0;
var totalRuns = 0;

for (var a = 0; a < ACTOR_IDS.length; a++) {
  var actorSlug = ACTOR_IDS[a];
  try {
    var runsRes = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.apify.com/v2/acts/' + actorSlug + '/runs?token=' + apifyToken + '&limit=100&desc=1'
    });
    var runs = (runsRes.data && runsRes.data.items) ? runsRes.data.items : [];
    for (var i = 0; i < runs.length; i++) {
      var run = runs[i];
      var startedAt = run.startedAt || '';
      if (startedAt < twoHoursAgo) { continue; }
      totalCostUsd += run.usageTotalUsd || 0;
      totalRuns++;
    }
  } catch (e) {}
}

return [{ json: {
  batchId: summary.batchId || '',
  runCompletedAt: summary.runCompletedAt || '',
  contacts_imported: summary.contacts_imported || 0,
  contacts_skipped_dedup: summary.contacts_skipped_dedup || 0,
  total_processed: summary.total_processed || 0,
  costUsd: totalCostUsd,
  totalRuns: totalRuns,
  'Date': today,
  'Workflow': 'Phase 1 - Discovery',
  'Actor': 'ig-hashtag-scraper + ig-profile-scraper',
  'Run ID': summary.batchId || '',
  'Actions Attempted': summary.total_processed || 0,
  'Actions Succeeded': summary.contacts_imported || 0,
  'Cost USD': totalCostUsd,
  'Status': (summary.contacts_imported || 0) + ' imported / ' + (summary.contacts_skipped_dedup || 0) + ' skipped (' + totalRuns + ' actor runs)'
} }];

var profile = $node['Loop Over Filtered Profiles'].json;
var batchId = '';
try { batchId = $node['Generate Batch ID'].json.batchId; } catch(e) {}

return [{
  json: {
    Username: profile.username || '',
    'Display Name': profile.displayName || '',
    Platform: profile.platform || '',
    Bio: profile.bio || '',
    'Follower Count': profile.followerCount || 0,
    'Following Count': profile.followingCount || 0,
    'Posts Count': profile.postsCount || 0,
    'Profile URL': profile.profileUrl || '',
    'Last Post Date': profile.lastPostDate || '',
    'Business Account': profile.isBusinessAccount ? 'Yes' : 'No',
    Verified: profile.isVerified ? 'Yes' : 'No',
    Website: profile.externalUrl || '',
    Location: profile.locationRaw || '',
    Email: profile.email || '',
    Phone: profile.phone || '',
    Category: profile.category || '',
    'Scrape Date': new Date().toISOString().split('T')[0],
    'Batch ID': batchId
  }
}];
